use super::*;
struct Recipient{bank:RetainedCloneGrant,deny:bool,reject:bool}
impl NativeDecodeConstructionRecipient for Recipient{fn grant(&mut self,_:RetirementDemand)->Result<RetainedCloneGrant,ValueError>{Ok(RetainedCloneGrant{maximum_items:usize::from(!self.deny),..self.bank})}fn accept(&mut self,g:RetainedCloneGrant,p:RetainedCloneProgress)->Result<(),ValueError>{assert!(p.fits(g));self.bank.maximum_items-=p.copied_items;self.bank.maximum_copy_bytes-=p.copied_bytes;self.bank.maximum_capacity_bytes-=p.retained_capacity_bytes;self.bank.maximum_release_bytes-=p.released_bytes;if self.reject{Err(ValueError::literal(ValueRefusalKind::WorkLimit,"actual construction recipient refused receipt"))}else{Ok(())}}}
#[test]fn actual_native_construction_keeps_null_input_and_born_output_with_both_refusals(){let row:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let s=&row["stock"];let mut recipient=Recipient{bank:RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize},deny:true,reject:false};let mut input=Some(row["value"].as_str().unwrap().to_owned());let pointer=input.as_ref().unwrap().as_ptr();let mut output=None;let mut callback=|_|true;let mut control=NativeDecodeControl::new(s["capacityBytes"].as_u64().unwrap()as usize,&mut callback);let mut fuel=s["fuel"].as_u64().unwrap();let turn=NativeOwnedDecodeControl::new(&mut control,&mut recipient).receive_shared(&mut input,&mut output,SharedIssuer::owned());assert_eq!(turn.work,row["deniedWork"].as_u64().unwrap());assert_eq!(turn.result.unwrap(),Default::default());assert_eq!(input.as_ref().unwrap().as_ptr(),pointer);assert!(output.is_none());recipient.deny=false;recipient.reject=true;
 let((turn,attempts),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||semio_framework_value_testing_allocator::refuse_one_allocation_on_this_thread(||NativeOwnedDecodeControl::new(&mut control,&mut recipient).receive_shared(&mut input,&mut output,SharedIssuer::owned())));assert_eq!(attempts,1);assert_eq!(heap,(0,0));assert_eq!(turn.work,row["nullWork"].as_u64().unwrap());fuel-=turn.work;let failure=turn.result.unwrap_err();assert!(failure.primary.is_some());assert!(failure.quote_refusal.is_some());assert_eq!(failure.progress,Default::default());assert_eq!(input.as_ref().unwrap().as_ptr(),pointer);assert!(output.is_none());assert_eq!(control.owned_bytes(),row["nullOwnedBytes"].as_u64().unwrap()as usize);
 let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||NativeOwnedDecodeControl::new(&mut control,&mut recipient).receive_shared(&mut input,&mut output,SharedIssuer::owned()));assert_eq!(turn.work,row["allocationWork"].as_u64().unwrap());fuel-=turn.work;let failure=turn.result.unwrap_err();assert!(failure.primary.is_none());assert!(failure.quote_refusal.is_some());assert_eq!(failure.progress.copied_bytes,row["copiedBytes"].as_u64().unwrap()as usize);assert_eq!(heap,(failure.progress.retained_capacity_bytes,failure.progress.released_bytes));assert!(input.is_none());assert_eq!(output.as_ref().unwrap().as_ptr(),pointer);assert_eq!(serde_json::to_value(output.as_ref().unwrap().get()).unwrap(),row["value"]);let mut owner=crate::retirement::controlled::ControlledRetirement::new(output.take().unwrap()).map_err(|(error,_)|error).unwrap();for _ in 0..s["maximumTurns"].as_u64().unwrap(){if owner.terminal_is_empty(){break}let step=owner.step(RetainedCloneGrant{maximum_items:1,..recipient.bank}).unwrap();fuel=fuel.checked_sub(owner.last_turn_work()).unwrap();let p=step.progress();recipient.reject=false;let g=RetainedCloneGrant{maximum_items:1,..recipient.bank};recipient.accept(g,p).unwrap();}assert!(owner.terminal_is_empty());assert!(fuel<s["fuel"].as_u64().unwrap());}
